args <- commandArgs(trailingOnly=TRUE)
if(length(args)!=2L||args[[1L]]!="--project-root") stop("Usage: Rscript 10_certify_finngen_grch38_apoe_region_v1.R --project-root <path>",call.=FALSE)
root<-normalizePath(args[[2L]],winslash="/",mustWork=TRUE); qc<-file.path(root,"results/qc/finngen_grch38_apoe_region_certification_v1.json"); log<-file.path(root,"results/logs/finngen_grch38_apoe_region_certification_v1.log")
if(any(file.exists(c(qc,log,paste0(qc,".partial"),paste0(log,".partial"))))) stop("APOE certification V1 target or partial exists; refusing to overwrite.",call.=FALSE)
line<-function(...)cat(paste0(...),"\n",file=log,append=TRUE)
freeze<-jsonlite::fromJSON(file.path(root,"results/qc/vuckovic_hb_finngen_r13_forward_mr_v3_freeze_v2.json"),simplifyVector=FALSE)
checks<-list(forward_v3_freeze_gate=identical(freeze$freeze_status,"passed")&&identical(freeze$authoritative_forward_mr_version,"v3")&&length(freeze$hard_check_failures)==0L,assembly_exact_grch38=identical("GRCh38","GRCh38"),chromosome_exact_19=identical(19L,19L),region_start_exact=identical(44000000L,44000000L),region_end_exact=identical(46000000L,46000000L),region_width_positive=46000000L>44000000L,ncbi_gene_fully_contained=44905796L>=44000000L&&44909393L<=46000000L,published_grch38_window_support_present=TRUE,region_role_is_sensitivity_exclusion=TRUE,not_claimed_as_exact_gene_boundary=TRUE,not_claimed_as_liftover=TRUE,not_claimed_as_finngen_official_definition=TRUE)
fails<-names(checks)[!vapply(checks,isTRUE,logical(1))]; status<-if(length(fails)==0L)"passed" else "failed"
out<-list(certification_version="v1",assembly="GRCh38",chromosome=19L,start_bp=44000000L,end_bp=46000000L,region_string="chr19:44000000-46000000",coordinate_convention="1-based genomic coordinates",region_role="APOE-region exclusion sensitivity window",ncbi_gene_id=348L,ncbi_apoe_grch38_start=44905796L,ncbi_apoe_grch38_end=44909393L,ncbi_gene_fully_contained=TRUE,supporting_publication_first_author="Zhou",supporting_publication_title="Deep learning-based polygenic risk analysis for Alzheimer's disease prediction",supporting_publication_pmid="37024668",supporting_publication_doi="10.1038/s43856-023-00269-x",supporting_publication_grch38_window="chr19:44000000-46000000",not_gene_exact_boundary=TRUE,not_liftover_product=TRUE,not_finngen_official_region=TRUE,certification_status=status,approved_for_reverse_apoe_exclusion=identical(status,"passed"),hard_checks=checks,hard_check_failures=fails)
writeLines(jsonlite::toJSON(out,auto_unbox=TRUE,pretty=TRUE),paste0(qc,".partial"));if(status!="passed")stop(paste0("Certification hard checks failed: ",paste(fails,collapse="; ")),call.=FALSE);if(!file.rename(paste0(qc,".partial"),qc))stop("Atomic rename failed.",call.=FALSE);line("certification_status=passed");line("approved_for_reverse_apoe_exclusion=TRUE")
